using Microsoft.EntityFrameworkCore;using InventoryService.Entities;namespace InventoryService.Data;public class InventoryDbContext(DbContextOptions<InventoryDbContext>o):DbContext(o){public DbSet<Product>Products=>Set<Product>();protected override void OnModelCreating(ModelBuilder m){var e=m.Entity<Product>();e.ToTable("products");e.HasKey(x=>x.ProductId);e.Property(x=>x.ProductId).HasColumnName("product_id").HasDefaultValueSql("gen_random_uuid()");e.Property(x=>x.ProductName).HasColumnName("product_name");e.Property(x=>x.StockQty).HasColumnName("stock_qty");e.Property(x=>x.IsActive).HasColumnName("is_active");e.Property(x=>x.CreatedAt).HasColumnName("created_at");e.Property(x=>x.UpdatedAt).HasColumnName("updated_at");}}